import{_ as t,c as s,o as a,ag as n}from"./chunks/framework.Ci10AEOF.js";const u=JSON.parse('{"title":"Security and Compliance","description":"TLS, CSRF and CORS settings, authentication, and encryption","frontmatter":{"title":"Security and Compliance","description":"TLS, CSRF and CORS settings, authentication, and encryption"},"headers":[],"relativePath":"engine/security_and_compliance.md","filePath":"engine/security_and_compliance.md","lastUpdated":1793057853000}'),o={name:"engine/security_and_compliance.md"};function i(r,e,c,l,h,d){return a(),s("div",null,e[0]||(e[0]=[n(`<h1 id="security-and-compliance" tabindex="-1">Security and Compliance <a class="header-anchor" href="#security-and-compliance" aria-label="Permalink to &quot;Security and Compliance&quot;">​</a></h1><p>The hardening checklist is on <a href="./security_posture_and_hardening.html#hardening-checklist">Security Posture and Hardening</a>.</p><h2 id="transport-layer-security-tls" tabindex="-1">Transport Layer Security (TLS) <a class="header-anchor" href="#transport-layer-security-tls" aria-label="Permalink to &quot;Transport Layer Security (TLS)&quot;">​</a></h2><h3 id="server-tls-configuration" tabindex="-1">Server TLS configuration <a class="header-anchor" href="#server-tls-configuration" aria-label="Permalink to &quot;Server TLS configuration&quot;">​</a></h3><p>These keys in <code>conf/mirth.properties</code> are read at startup. <code>https.server.protocols</code> goes to the HTTPS listener that serves the REST API and the Administrator, and to the DICOM Listener. <code>https.client.protocols</code> covers TLS connections the server opens (HTTP Sender, Web Service Sender, SMTP Sender, DICOM Sender, alert email). <code>https.ciphersuites</code> is one list shared by the HTTPS listener and by the HTTP Sender, Web Service Sender, SMTP Sender and alert email, so shortening it for the listener also changes what those senders negotiate; the DICOM connectors read the protocol lists only. When <code>https.client.protocols</code> or <code>https.ciphersuites</code> differs from the shipped value, the server also writes both into the launch file (<code>webstart.jnlp</code>) that starts the desktop Administrator, and an Administrator started from it uses them for its connection to the server. The cipher suite list is split on commas, and any name the JVM does not support is dropped before the rest are enabled, so a misspelt name is ignored rather than reported. <code>https.ephemeraldhkeysize</code> is copied into the JVM&#39;s <code>jdk.tls.ephemeralDHKeySize</code>, clamped to 1024 through 2048, unless that system property is already set. The block shows the shipped defaults.</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># TLS protocol versions for connections the server opens</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">https.client.protocols</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = TLSv1.3,TLSv1.2</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># TLS protocol versions accepted by the HTTPS listener</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">https.server.protocols</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = TLSv1.3,TLSv1.2,SSLv2Hello</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Enabled cipher suites, comma-separated on one line</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">https.ciphersuites</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = TLS_CHACHA20_POLY1305_SHA256,TLS_ECDHE_ECDSA_WITH_CHACHA20_POLY1305_SHA256,TLS_ECDHE_RSA_WITH_CHACHA20_POLY1305_SHA256,TLS_DHE_RSA_WITH_CHACHA20_POLY1305_SHA256,TLS_AES_256_GCM_SHA384,TLS_AES_128_GCM_SHA256,TLS_ECDHE_ECDSA_WITH_AES_256_GCM_SHA384,TLS_ECDHE_RSA_WITH_AES_256_GCM_SHA384,TLS_RSA_WITH_AES_256_GCM_SHA384,TLS_ECDH_ECDSA_WITH_AES_256_GCM_SHA384,TLS_ECDH_RSA_WITH_AES_256_GCM_SHA384,TLS_DHE_RSA_WITH_AES_256_GCM_SHA384,TLS_DHE_DSS_WITH_AES_256_GCM_SHA384,TLS_ECDHE_ECDSA_WITH_AES_128_GCM_SHA256,TLS_ECDHE_RSA_WITH_AES_128_GCM_SHA256,TLS_RSA_WITH_AES_128_GCM_SHA256,TLS_ECDH_ECDSA_WITH_AES_128_GCM_SHA256,TLS_ECDH_RSA_WITH_AES_128_GCM_SHA256,TLS_DHE_RSA_WITH_AES_128_GCM_SHA256,TLS_DHE_DSS_WITH_AES_128_GCM_SHA256,TLS_EMPTY_RENEGOTIATION_INFO_SCSV</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Ephemeral Diffie-Hellman key size in bits</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">https.ephemeraldhkeysize</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = 2048</span></span></code></pre></div><h3 id="keystore-management" tabindex="-1">Keystore management <a class="header-anchor" href="#keystore-management" aria-label="Permalink to &quot;Keystore management&quot;">​</a></h3><p>The keystore holds the certificate the HTTPS listener presents and the secret key behind the server&#39;s encryptor. These keys in <code>conf/mirth.properties</code> name it. On the first start with no keystore file, the server creates one, generates a certificate authority and a server certificate signed by it (both valid for 50 years), and, when both passwords still equal the shipped default <code>81uWxplDtB</code>, replaces them with random 12-character values and writes <code>mirth.properties</code> back. A keystore file that already exists at <code>keystore.path</code> is loaded with whatever <code>mirth.properties</code> holds, default included, and when only one of the two passwords was changed by hand neither is replaced. The block shows the keys as they stand after a first start that created the keystore; the passwords are placeholders for the generated values, so do not paste this block.</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">keystore.path</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = \${dir.appdata}/keystore.jks</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">keystore.storepass</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = (generated)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">keystore.keypass</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = (generated)</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">keystore.type</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = JCEKS</span></span></code></pre></div><p>Passwords set by hand before the first start are kept as they are. The <a href="https://github.com/NovaMap-Health/tls-manager-plugin" target="_blank" rel="noreferrer">TLS Manager</a> community extension keeps its own certificates and key pairs, in the database by default, and adds a web certificate manager that also lists the Java trust store; it is not part of the engine.</p><h3 id="connector-level-tls" tabindex="-1">Connector-level TLS <a class="header-anchor" href="#connector-level-tls" aria-label="Permalink to &quot;Connector-level TLS&quot;">​</a></h3><p>What each connector encrypts:</p><ul><li><strong>HTTP Sender</strong> and <strong>Web Service Sender</strong>: an <code>https://</code> URL opens a TLS connection using <code>https.client.protocols</code> and <code>https.ciphersuites</code></li><li><strong>SMTP Sender</strong>: the Encryption setting is None, STARTTLS (upgrades the connection after connecting) or SSL (TLS on connect), with the same protocol and cipher suite lists</li><li><strong>File Reader/Writer</strong>: SFTP, HTTPS for the WebDAV scheme, and HTTPS to the AWS endpoint for the configured region for the Amazon S3 scheme. FTP is plain; there is no FTPS. The SMB scheme sets the minimum and maximum SMB version and has no encryption setting</li><li><strong>Database Reader/Writer</strong>: no TLS setting of its own; encryption depends on the JDBC driver and the URL</li><li><strong>JMS Listener/Sender</strong>: no TLS setting of its own; encryption depends on the JMS provider&#39;s configuration</li><li><strong>DICOM Listener/Sender</strong>: a TLS setting on each connector (No TLS, AES, 3DES, or Without) with its own key store and trust store; the listener uses <code>https.server.protocols</code>, the sender <code>https.client.protocols</code>. With the JDK&#39;s default security settings on Java 17 and 21, 3DES, AES and Without fail; see the box under <a href="./connector_reference_sources.html#dicom-listener">DICOM Listener</a></li><li><strong>TCP Listener/Sender</strong>, <strong>HTTP Listener</strong> and <strong>Web Service Listener</strong>: plain sockets and plain HTTP. Each builds its connections from a class named in a server property (<code>tcpConfigurationClass</code>, <code>httpConfigurationClass</code>, <code>wsConfigurationClass</code>), which an extension can set to a class that adds TLS; the engine ships none</li></ul><p>The <a href="https://github.com/NovaMap-Health/tls-manager-plugin" target="_blank" rel="noreferrer">TLS Manager</a> community extension replaces the HTTP, Web Service and TCP connectors with TLS-capable ones, listeners and senders both. It adds mTLS, certificate revocation checks (CRL and OCSP), subject DN and hostname validation, and the permitted TLS versions and cipher suites per connector, and it supports OIE 4.5.2 and later.</p><h2 id="csrf-protection" tabindex="-1">CSRF protection <a class="header-anchor" href="#csrf-protection" aria-label="Permalink to &quot;CSRF protection&quot;">​</a></h2><p>The REST API requires an <code>X-Requested-With</code> header by default. The key in <code>conf/mirth.properties</code>:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.api.require-requested-with</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = true</span></span></code></pre></div><p>The header&#39;s value is not inspected; any non-blank value passes. A request without it gets HTTP 400 and never reaches the API. This is the Cross-Site Request Forgery guard, and every API client must send the header.</p><h2 id="cors-configuration" tabindex="-1">CORS configuration <a class="header-anchor" href="#cors-configuration" aria-label="Permalink to &quot;CORS configuration&quot;">​</a></h2><p>The <code>ApiOriginFilter</code> reads six keys from <code>conf/mirth.properties</code> at startup and adds the matching <code>Access-Control-*</code> header to every API response. A key left blank adds no header. The block shows the shipped values:</p><div class="language-properties vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">properties</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># CORS headers</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.api.accesscontrolalloworigin</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = *</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.api.accesscontrolallowcredentials</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = false</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.api.accesscontrolallowmethods</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = GET, POST, DELETE, PUT</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.api.accesscontrolallowheaders</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> = Content-Type</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.api.accesscontrolexposeheaders</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> =</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">server.api.accesscontrolmaxage</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> =</span></span></code></pre></div><p><code>accesscontrolalloworigin</code> is sent verbatim as <code>Access-Control-Allow-Origin</code>; the filter does not compare it with the request&#39;s <code>Origin</code> header, and the header takes a single origin or <code>*</code>. <code>accesscontrolallowcredentials</code> is sent as <code>true</code> or <code>false</code>, and <code>accesscontrolmaxage</code> as a number of seconds, falling back to <code>300</code> when the value does not parse. Keep comments on their own line: everything after the <code>=</code> is the value, so a trailing <code># note</code> would be sent as part of the header.</p><p>Set <code>server.api.accesscontrolalloworigin</code> to the one origin that needs access instead of <code>*</code>.</p><h2 id="authentication-and-access-control" tabindex="-1">Authentication and access control <a class="header-anchor" href="#authentication-and-access-control" aria-label="Permalink to &quot;Authentication and access control&quot;">​</a></h2><h3 id="password-policy" tabindex="-1">Password policy <a class="header-anchor" href="#password-policy" aria-label="Permalink to &quot;Password policy&quot;">​</a></h3><p>The shipped <code>conf/mirth.properties</code> sets <code>password.minlength = 15</code>, <code>password.retrylimit = 100</code> and <code>password.lockoutperiod = 1</code>. Every other <code>password.*</code> key ships at <code>0</code>, which turns its check off. <a href="./user_management.html#password-policy">User Management</a> lists every key and what each one controls.</p><h3 id="account-lockout" tabindex="-1">Account lockout <a class="header-anchor" href="#account-lockout" aria-label="Permalink to &quot;Account lockout&quot;">​</a></h3><p>Lockout after failed logins is on as shipped (<code>password.retrylimit = 100</code>, <code>password.lockoutperiod = 1</code>). Two keys control it:</p><ul><li><code>password.retrylimit</code>: Consecutive failed logins allowed before the account locks; <code>0</code> disables lockout</li><li><code>password.lockoutperiod</code>: Hours the account stays locked, counted from the last failed login; <code>0</code> means the account never locks, whatever <code>password.retrylimit</code> says</li></ul><p>A failed login gets the same response whatever the cause: a wrong password, an unknown username and a locked account all return <code>FAIL</code> with the message <code>Login failed.</code>, and take about the same time. When an account locks, the server logs a <code>User account locked</code> event at Warning level with the username and the time the lock ends.</p><div class="danger custom-block"><p class="custom-block-title">Broken in 4.7.0</p><p>Failed logins show which usernames exist. With lockout on, a failed login for an existing account says how many attempts are left before it locks, and a locked account&#39;s login says when it unlocks, while an unknown username gets only <code>Incorrect username or password.</code> Response time shows it too, with or without lockout: a login for an unknown username returns sooner than one for a real account. Reported in <a href="https://github.com/OpenIntegrationEngine/engine/issues/240" target="_blank" rel="noreferrer">engine issue #240</a>; fixed by <a href="https://github.com/OpenIntegrationEngine/engine/pull/439" target="_blank" rel="noreferrer">engine PR #439</a>, merged after 4.7.0, not yet in a release.</p></div><p>Keep the Administrator and API port on an administrative network; see <a href="./security_posture_and_hardening.html#network-placement">Network placement</a>.</p><h3 id="multi-factor-authentication" tabindex="-1">Multi-factor authentication <a class="header-anchor" href="#multi-factor-authentication" aria-label="Permalink to &quot;Multi-factor authentication&quot;">​</a></h3><p>Multi-factor authentication comes from an extension. A plugin that extends <code>MultiFactorAuthenticationPlugin</code> runs after the password check succeeds and asks for the second factor through its client-side part. The engine ships none.</p><h3 id="role-based-access-control-rbac" tabindex="-1">Role-based access control (RBAC) <a class="header-anchor" href="#role-based-access-control-rbac" aria-label="Permalink to &quot;Role-based access control (RBAC)&quot;">​</a></h3><p>The engine has no role model: every user is authorized for every operation, so every account can do everything the API allows. The <a href="https://openintegrationengine.org/plugins/" target="_blank" rel="noreferrer">Role Based Access Control</a> community extension adds roles and per-channel grants.</p><h2 id="encryption" tabindex="-1">Encryption <a class="header-anchor" href="#encryption" aria-label="Permalink to &quot;Encryption&quot;">​</a></h2><h3 id="data-at-rest" tabindex="-1">Data at rest <a class="header-anchor" href="#data-at-rest" aria-label="Permalink to &quot;Data at rest&quot;">​</a></h3><ul><li>With <code>encryption.properties = 1</code> in <code>conf/mirth.properties</code> (the key is not in the shipped file and defaults to off), the server encrypts <code>database.password</code> and <code>database-readonly.password</code> with the keystore&#39;s secret key at the next start and writes them back to <code>mirth.properties</code> with an <code>{enc}</code> prefix; the keystore holds the key, not the credential</li><li>The <code>EncryptionUtil</code> scripting class encrypts and decrypts strings and byte arrays with the server&#39;s encryptor, which is keyed from the keystore and uses <code>AES/CBC/PKCS5Padding</code> by default</li><li>Each channel&#39;s Message Storage settings on the Summary tab can encrypt what the channel writes to the database: <strong>Encrypt message content</strong>, <strong>Attachments</strong> and <strong>Custom metadata</strong>, each with the keystore&#39;s secret key. All three are off by default. An attachment a script adds with <code>addAttachment()</code> is stored in plain text even with <strong>Attachments</strong> on</li><li>Files the Administrator exports, such as channels, are encrypted with the same key when <code>encryption.export = 1</code> (off as shipped), and so are message exports and archives with the Encrypt option on</li></ul><h3 id="data-in-transit" tabindex="-1">Data in transit <a class="header-anchor" href="#data-in-transit" aria-label="Permalink to &quot;Data in transit&quot;">​</a></h3><ul><li>Logins and REST API traffic use TLS on the engine&#39;s HTTPS port (<code>https.port</code>, 8443 as shipped). The status page, <code>webstart.jnlp</code> and the jars the desktop Administrator downloads are also served on the HTTP port (<code>http.port</code>, 8080 as shipped) when it is enabled, which it is by default</li><li>Connectors: see <a href="#connector-level-tls">Connector-level TLS</a></li></ul><h3 id="keystore" tabindex="-1">Keystore <a class="header-anchor" href="#keystore" aria-label="Permalink to &quot;Keystore&quot;">​</a></h3><p>The JCEKS keystore holds two entries:</p><ul><li>The HTTPS listener&#39;s certificate and private key, alias <code>mirthconnect</code></li><li>The secret key of the server&#39;s encryptor, alias <code>encryption</code></li></ul><h2 id="reporting-security-vulnerabilities" tabindex="-1">Reporting security vulnerabilities <a class="header-anchor" href="#reporting-security-vulnerabilities" aria-label="Permalink to &quot;Reporting security vulnerabilities&quot;">​</a></h2><p>Report vulnerabilities confidentially to the Eclipse Foundation Security Team at <strong><a href="mailto:security@eclipse-foundation.org" target="_blank" rel="noreferrer">security@eclipse-foundation.org</a></strong>, following the process at <a href="https://www.eclipse.org/security/" target="_blank" rel="noreferrer">eclipse.org/security</a>. The engine&#39;s <a href="https://github.com/OpenIntegrationEngine/engine/blob/main/SECURITY.md" target="_blank" rel="noreferrer">SECURITY.md</a> has the policy.</p>`,46)]))}const g=t(o,[["render",i]]);export{u as __pageData,g as default};
